selector_to_html = {"a[href=\"#q3-dind-dood\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q3: DinD \u548c DooD \u6709\u4ec0\u4e48\u533a\u522b\uff1f<a class=\"headerlink\" href=\"#q3-dind-dood\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#q5-coverage\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q5: \u5982\u4f55\u4e0a\u4f20 Coverage \u62a5\u544a\uff1f<a class=\"headerlink\" href=\"#q5-coverage\" title=\"Link to this heading\">#</a></h2><p>\u9700\u7528\u6237\u624b\u52a8\u5728 workflow \u4e2d\u7528 pytest \u4ea7\u51fa json \u683c\u5f0f\u7684\u62a5\u544a\uff0c\u7136\u540e\u8c03\u7528 FlagOps \u63d0\u4f9b\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">post-pytest-report</span></code> action \u4e0a\u4f20\u3002</p>", "a[href=\"#q9\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q9: \u6a21\u578b\u5220\u9664\u540e\u6587\u4ef6\u4f1a\u5220\u9664\u5417\uff1f<a class=\"headerlink\" href=\"#q9\" title=\"Link to this heading\">#</a></h2><p>\u6682\u65f6\u53ea\u5220\u9664\u6570\u636e\u5e93\uff0c\u6587\u4ef6\u5b9e\u9645\u5e95\u5c42\u5f53\u524d\u56e0\u5b9e\u73b0\u9650\u5236\u4e0d\u652f\u6301\u5220\u9664\uff0c\u540e\u7eed\u4f1a\u8fed\u4ee3\u652f\u6301\u3002</p>", "a[href=\"../glossary/index.html#term-DooD\"]": "<dt id=\"term-DooD\">DooD</dt><dd><p>Docker-outside-of-Docker\uff0c\u4f7f\u7528\u5bbf\u4e3b\u673a Docker daemon \u7684\u5bb9\u5668\u5316\u65b9\u6848\uff0c\u6027\u80fd\u9ad8\u4f46\u98ce\u9669\u9ad8\uff0c\u4ec5\u5bf9\u7279\u6743\u7528\u6237\u5f00\u653e\u3002</p></dd>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e38\u89c1\u95ee\u9898<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>Q1: \u8bbf\u95ee\u4ee4\u724c\u9700\u8981\u4ec0\u4e48\u6743\u9650\uff1f<a class=\"headerlink\" href=\"#q1\" title=\"Link to this heading\">#</a></h2><p>\u8bbf\u95ee\u4ee4\u724c\u9700\u8981 Admin \u7684\u5199\u6743\u9650\uff0c\u7528\u4e8e runner \u7684\u521b\u5efa\u3002</p>", "a[href=\"#q7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q7: \u7528\u6237\u6ce8\u518c\u540e\u4e3a\u4ec0\u4e48\u6ca1\u6709\u6743\u9650\uff1f<a class=\"headerlink\" href=\"#q7\" title=\"Link to this heading\">#</a></h2><p>\u5e73\u53f0\u6ce8\u518c\u7528\u6237\u9ed8\u8ba4\u65e0\u89d2\u8272\uff0c\u9700\u7ba1\u7406\u5458\u624b\u52a8\u5206\u914d\u89d2\u8272\u540e\u624d\u80fd\u4f7f\u7528\u5e73\u53f0\u529f\u80fd\u3002</p>", "a[href=\"#q4-gitlink-github\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q4: GitLink \u76f8\u6bd4 GitHub \u6709\u4ec0\u4e48\u9650\u5236\uff1f<a class=\"headerlink\" href=\"#q4-gitlink-github\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../glossary/index.html#term-DinD\"]": "<dt id=\"term-DinD\">DinD</dt><dd><p>Docker-in-Docker\uff0c\u5728 Docker \u5bb9\u5668\u5185\u8fd0\u884c Docker \u7684\u6280\u672f\u65b9\u6848\uff0c\u9694\u79bb\u6027\u597d\u4f46 docker run \u4e0d\u53ef\u8bbf\u95ee\u52a0\u901f\u5361\u8d44\u6e90\u3002</p></dd>", "a[href=\"#q8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q8: \u5982\u4f55\u6dfb\u52a0\u4ed3\u5e93\u6210\u5458\uff1f<a class=\"headerlink\" href=\"#q8\" title=\"Link to this heading\">#</a></h2><p>\u4ed3\u5e93\u7ba1\u7406\u5458\u53ef\u5728\u4ed3\u5e93\u8be6\u60c5 \u2192 \u8bbe\u7f6e \u2192 \u6210\u5458\u7ba1\u7406\u4e2d\u6dfb\u52a0\u6210\u5458\uff0c\u53ef\u641c\u7d22\u5230\u7684\u8303\u56f4\u4e3a\u6b63\u5e38\u4e14\u975e\u672a\u8bbe\u7f6e\u89d2\u8272\u7684\u7528\u6237\u3002</p>", "a[href=\"#q6-benchmark\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q6: \u5982\u4f55\u4e0a\u4f20 Benchmark \u62a5\u544a\uff1f<a class=\"headerlink\" href=\"#q6-benchmark\" title=\"Link to this heading\">#</a></h2><p>\u751f\u4ea7\u8868\u683c\u6570\u636e\uff08JSON \u683c\u5f0f\uff09\uff0c\u7136\u540e\u8c03\u7528 FlagOps \u63d0\u4f9b\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">post-benchmark-report</span></code> action \u4e0a\u4f20\u3002</p>", "a[href=\"#q10-workflow\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q10: \u5982\u4f55\u5728 workflow \u4e2d\u4f7f\u7528\u5171\u4eab\u5b58\u50a8\u6570\u636e\uff1f<a class=\"headerlink\" href=\"#q10-workflow\" title=\"Link to this heading\">#</a></h2><p>\u5982\u679c\u9700\u8981\u5171\u4eab\u5b58\u50a8\u4e2d\u7684\u6570\u636e\uff0c\u5fc5\u987b\u5728\u542f\u52a8 container \u65f6\u6302\u8f7d\u5230 container \u4e2d\uff1a</p>", "a[href=\"#q2-runner-max-min-runners\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q2: Runner \u7684 Max \u548c Min Runners \u5e94\u8be5\u5982\u4f55\u8bbe\u7f6e\uff1f<a class=\"headerlink\" href=\"#q2-runner-max-min-runners\" title=\"Link to this heading\">#</a></h2><p>\u7531\u4e8e\u8d44\u6e90\u6709\u9650\uff0cMax Runners \u5f53\u524d\u5efa\u8bae\u8bbe\u4e3a 1\uff0cMin Runners \u8bbe\u7f6e\u4e3a 0\u3002</p>", "a[href=\"#q1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q1: \u8bbf\u95ee\u4ee4\u724c\u9700\u8981\u4ec0\u4e48\u6743\u9650\uff1f<a class=\"headerlink\" href=\"#q1\" title=\"Link to this heading\">#</a></h2><p>\u8bbf\u95ee\u4ee4\u724c\u9700\u8981 Admin \u7684\u5199\u6743\u9650\uff0c\u7528\u4e8e runner \u7684\u521b\u5efa\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
